arguments.file_text:
@page "/dispatch"
@attribute [Authorize(Roles = "Dispatcher")]
@inject IShipmentService ShipmentService

<PageTitle>Dispatch - ShipmentTracker</PageTitle>

<h1>Dispatch Dashboard</h1>

<div class="mb-3">
    <input type="text" class="form-control" placeholder="Filter by tracking number or destination..."
           @bind="filterText" @bind:event="oninput" />
</div>

@if (shipments is null)
{
    <p><em>Loading shipments...</em></p>
}
else
{
    <table class="table table-striped">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Shipped Date</th>
                <th>Est. Delivery</th>
                <th>Update Status</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var shipment in FilteredShipments)
            {
                <tr>
                    <td>@shipment.TrackingNumber</td>
                    <td>@shipment.Destination</td>
                    <td><span class="badge bg-info">@shipment.Status</span></td>
                    <td>@shipment.ShippedDate.ToString("yyyy-MM-dd")</td>
                    <td>@shipment.EstimatedDelivery?.ToString("yyyy-MM-dd")</td>
                    <td>
                        <select class="form-select form-select-sm"
                                value="@shipment.Status"
                                @onchange="(e) => OnStatusChanged(shipment.Id, e)">
                            @foreach (var status in Enum.GetValues<ShipmentStatus>())
                            {
                                <option value="@status" selected="@(status == shipment.Status)">@status</option>
                            }
                        </select>
                    </td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<Shipment>? shipments;
    private string filterText = string.Empty;

    private IEnumerable<Shipment> FilteredShipments =>
        shipments?.Where(s =>
            string.IsNullOrEmpty(filterText) ||
            s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
            s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase)) ?? [];

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private async Task OnStatusChanged(int id, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
        {
            await ShipmentService.UpdateShipmentStatusAsync(id, newStatus);
            shipments = await ShipmentService.GetAllShipmentsAsync();
        }
    }
}

@page "/track"
@attribute [Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment - ShipmentTracker</PageTitle>

<h1>Track a Shipment</h1>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number..."
                   @bind="trackingNumber" @bind:event="oninput" @onkeydown="OnKeyDown" />
            <button class="btn btn-primary" @onclick="TrackShipment">Track</button>
        </div>
    </div>
</div>

@if (searchPerformed)
{
    @if (trackedShipment is not null)
    {
        <div class="card mb-4">
            <div class="card-header">
                <h5>Shipment: @trackedShipment.TrackingNumber</h5>
            </div>
            <div class="card-body">
                <dl class="row">
                    <dt class="col-sm-3">Status</dt>
                    <dd class="col-sm-9"><span class="badge bg-info">@trackedShipment.Status</span></dd>

                    <dt class="col-sm-3">Origin</dt>
                    <dd class="col-sm-9">@trackedShipment.Origin</dd>

                    <dt class="col-sm-3">Destination</dt>
                    <dd class="col-sm-9">@trackedShipment.Destination</dd>

                    <dt class="col-sm-3">Shipped Date</dt>
                    <dd class="col-sm-9">@trackedShipment.ShippedDate.ToString("yyyy-MM-dd")</dd>

                    <dt class="col-sm-3">Estimated Delivery</dt>
                    <dd class="col-sm-9">@(trackedShipment.EstimatedDelivery?.ToString("yyyy-MM-dd") ?? "N/A")</dd>

                    <dt class="col-sm-3">Actual Delivery</dt>
                    <dd class="col-sm-9">@(trackedShipment.ActualDelivery?.ToString("yyyy-MM-dd") ?? "Not yet delivered")</dd>

                    <dt class="col-sm-3">Description</dt>
                    <dd class="col-sm-9">@trackedShipment.Description</dd>
                </dl>
            </div>
        </div>
    }
    else
    {
        <div class="alert alert-warning">No shipment found with tracking number "@trackingNumber".</div>
    }
}

<hr />

<h2>My Shipments</h2>

@if (myShipments is null)
{
    <p><em>Loading your shipments...</em></p>
}
else if (myShipments.Count == 0)
{
    <p>You have no shipments associated with your account.</p>
}
else
{
    <table class="table table-striped">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Shipped Date</th>
                <th>Est. Delivery</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var shipment in myShipments)
            {
                <tr>
                    <td>@shipment.TrackingNumber</td>
                    <td>@shipment.Destination</td>
                    <td><span class="badge bg-info">@shipment.Status</span></td>
                    <td>@shipment.ShippedDate.ToString("yyyy-MM-dd")</td>
                    <td>@shipment.EstimatedDelivery?.ToString("yyyy-MM-dd")</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private string trackingNumber = string.Empty;
    private Shipment? trackedShipment;
    private List<Shipment>? myShipments;
    private bool searchPerformed;

    protected override async Task OnInitializedAsync()
    {
        myShipments = await ShipmentService.GetShipmentsByCustomerAsync(string.Empty);
    }

    private async Task TrackShipment()
    {
        if (!string.IsNullOrWhiteSpace(trackingNumber))
        {
            trackedShipment = await ShipmentService.GetShipmentByTrackingNumberAsync(trackingNumber.Trim());
            searchPerformed = true;
        }
    }

    private async Task OnKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
        {
            await TrackShipment();
        }
    }
}

