             </div>
             <div class="card-body">
                 <dl class="row">
                     <dt class="col-sm-3">Status</dt>
                     <dd class="col-sm-9"><span class="badge bg-info">@trackedShipment.Status</span></dd>

                     <dt class="col-sm-3">Origin</dt>
                     <dd class="col-sm-9">@trackedShipment.Origin</dd>

                     <dt class="col-sm-3">Destination</dt>
                     <dd class="col-sm-9">@trackedShipment.Destination</dd>

                     <dt class="col-sm-3">Shipped Date</dt>
                     <dd class="col-sm-9">@trackedShipment.ShippedDate.ToString("yyyy-MM-dd")</dd>

                     <dt class="col-sm-3">Estimated Delivery</dt>
                     <dd class="col-sm-9">@(trackedShipment.EstimatedDelivery?.ToString("yyyy-MM-dd") ?? "N/A")</dd>

                     <dt class="col-sm-3">Actual Delivery</dt>
                     <dd class="col-sm-9">@(trackedShipment.ActualDelivery?.ToString("yyyy-MM-dd") ?? "Not yet delivered")</dd>

                     <dt class="col-sm-3">Description</dt>
                     <dd class="col-sm-9">@trackedShipment.Description</dd>
                 </dl>
             </div>
         </div>
     }
     else
     {
         <div class="alert alert-warning">No shipment found with tracking number "@trackingNumber".</div>
     }
 }

 <hr />

 <h2>My Shipments</h2>

 @if (myShipments is null)
 {
     <p><em>Loading your shipments...</em></p>
 }
 else if (myShipments.Count == 0)
 {
     <p>You have no shipments associated with your account.</p>
 }
 else
 {
     <table class="table table-striped">
         <thead>
             <tr>
                 <th>Tracking #</th>
                 <th>Destination</th>
                 <th>Status</th>
                 <th>Shipped Date</th>
                 <th>Est. Delivery</th>
             </tr>
         </thead>
         <tbody>
             @foreach (var shipment in myShipments)
             {
                 <tr>
                     <td>@shipment.TrackingNumber</td>
                     <td>@shipment.Destination</td>
                     <td><span class="badge bg-info">@shipment.Status</span></td>
                     <td>@shipment.ShippedDate.ToString("yyyy-MM-dd")</td>
                     <td>@shipment.EstimatedDelivery?.ToString("yyyy-MM-dd")</td>
                 </tr>
             }
         </tbody>
     </table>
 }

 @code {
     private string trackingNumber = string.Empty;
     private Shipment? trackedShipment;
     private List<Shipment>? myShipments;
     private bool searchPerformed;

     protected override async Task OnInitializedAsync()
     {
         myShipments = await ShipmentService.GetShipmentsByCustomerAsync(string.Empty);
     }

     private async Task SearchShipment()
     {
         if (!string.IsNullOrWhiteSpace(trackingNumber))
         {
             trackedShipment = await ShipmentService.GetShipmentByTrackingNumberAsync(trackingNumber.Trim());
             searchPerformed = true;
         }
     }

     private async Task OnKeyDown(KeyboardEventArgs e)
     {
         if (e.Key == "Enter")
         {
             await SearchShipment();
         }
     }
 }

